/**
 * @file Table canonical identity and opt-in admission.
 * @input Complete logical data, idKey and declared plugin capabilities.
 * @output Type-preserving row identities and order-independent admission.
 * @position Private parent protocol; never a plugin-specific extractor.
 */

export function resolveTableIdentity(data, idKey, usesCanonicalIdentity) {
  const counts = new Map();
  const rows = data.map((item, index) => {
    if (!usesCanonicalIdentity) {
      const key = idKey == null ? index : typeof idKey === 'function' ? idKey(item) : String(item[idKey]);
      return {
        key,
        reactKey: key,
        identityStatus: 'valid'
      };
    }
    if (idKey == null) {
      return {
        key: undefined,
        reactKey: `invalid:${index}`,
        identityStatus: 'missing'
      };
    }
    let raw;
    try {
      raw = typeof idKey === 'function' ? idKey(item) : item[idKey];
    } catch {
      return {
        key: undefined,
        reactKey: `invalid:${index}`,
        identityStatus: 'invalid'
      };
    }
    if (typeof raw !== 'string' && (typeof raw !== 'number' || !Number.isFinite(raw))) {
      return {
        key: undefined,
        reactKey: `invalid:${index}`,
        identityStatus: 'invalid'
      };
    }
    const key = typeof idKey === 'function' ? raw : String(raw);
    counts.set(key, (counts.get(key) ?? 0) + 1);
    return {
      key,
      reactKey: `${typeof key === 'number' ? 'n' : 's'}:${key}`,
      identityStatus: 'valid'
    };
  });
  if (!usesCanonicalIdentity) {
    return rows;
  }
  return rows.map((row, index) => row.key != null && (counts.get(row.key) ?? 0) > 1 ? {
    ...row,
    identityStatus: 'duplicate',
    reactKey: `duplicate:${index}`
  } : row);
}
export function resolveTableAdmission(plugins) {
  const modifier = plugins.find(plugin => plugin.rowModel !== 'flat' && (plugin.rowModel != null || plugin.transformBodyRow != null || plugin.transformBodyCell != null));
  const rowModel = modifier?.rowModel ?? (modifier ? 'custom' : 'flat');
  return {
    rowModel
  };
}